WITH cleaned AS (SELECT id, order_id, method, paid_at, status, CAST(amount AS INT) AS amount_int, COALESCE(method, 'UNKNOWN') AS resolved_method FROM payments WHERE order_id IS NOT NULL AND method IS NOT DISTINCT FROM 'card') SELECT d.channel, src.method, COUNT(*) AS cnt, MIN(src.amount_int) AS min_amount_int FROM cleaned src JOIN orders d ON src.order_id = d.id GROUP BY GROUPING SETS ((d.channel, src.method), (d.channel), ()) ORDER BY channel ASC NULLS FIRST
